def encode(self, text: str, chunk_size: int = 4000) -> list[list[int]]:
    return [self._encode(chunk) for chunk in self.chunk_text(text, chunk_size)]

@staticmethod
def chunk_text(text: str, chunk_size: int) -> list[str]:
    return [text[i:i+chunk_size] for i in range(0, len(text), chunk_size)]

